/*
 * A127452  Triangle, read by rows of n*(n+1)/2 + 1 terms, generated by the
 *          recurrence: start with a single '1' in row 0; row n+1 is generated
 *          from row n by first inserting zeros at positions {(m+1)*(m+2)/2 -
 *          1, m>=0} in row n and then taking the partial sums in reverse
 *          order.
 * https://oeis.org/A127452
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   not stated
 * Range:     u8 n <= 40, u16 n <= 128, u32 n <= 376, u64 n <= 1560,
 *            u128 n <= 4990, big any n
 * Helpers:   small_fact
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A127452: Triangle read by rows; a(n) is the linear index of the
 * triangle defined by:
 *   T(0,0) = 1
 *   For n≥0, t = floor((sqrt(8k+1)-1)/2) where k is the column.
 *   T(n,k) = (n-t)! · (n-t)^(k - t(t+1)/2) · (n-t+1)^(t - k + t(t+1)/2).
 *   a(n) is T(row, column) where (row,column) is the location that
 *   occupies the n‑th position when the rows are concatenated.
 *
 * The implementation below avoids external utilities by computing
 * t with a small integer loop, factorial by simple multiplication,
 * and powers by fast exponentiation in seq_t.
 */

#include <stdint.h>
#include <stdbool.h>
#include "../utils/small_fact.h"

/* ---------- Helper: small integer power for seq_t values ---------- */
static inline seq_t pow_seq(seq_t base, idx_t exp)
{
    seq_t result = 1;
    while (exp) {
        if (exp & 1U) result *= base;
        base *= base;
        exp >>= 1;
    }
    return result;
}

/* ---------- Main sequence function ---------- */
seq_t a(idx_t n)
{
    /* Find the row (r) and column (k) corresponding to linear index n. */
    idx_t r = 0;
    idx_t cumulative = 0;                     /* total elements before current row */

    for (;;) {
        idx_t row_len = r * (r + 1) / 2 + 1; /* length of row r */
        if (cumulative + row_len > n)
            break;
        cumulative += row_len;
        ++r;
    }
    idx_t k = n - cumulative;                  /* column index within row r */

    /* Compute t = floor((sqrt(8k+1)-1)/2) by integer scanning. */
    idx_t t = 0;
    for (; (t + 1) * (t + 2) / 2 <= k; ++t)
        ;                                       /* empty loop body */

    /* Intermediate exponents. */
    idx_t tri_t = t * (t + 1) / 2;
    idx_t exp1  = k - tri_t;                    /* exponent for (r-t)   */
    idx_t exp2  = t - k + tri_t;                /* exponent for (r-t+1) */

    /* Base values. */
    idx_t nt = r - t;                           /* n-t                 */
    seq_t base1 = (seq_t)nt;
    seq_t base2 = (seq_t)(nt + 1);

    /* Compute the factorial part (n-t)! . */
    seq_t fact = small_fact(nt);

    /* Compute the power terms. */
    seq_t pow1 = pow_seq(base1, exp1);
    seq_t pow2 = pow_seq(base2, exp2);

    /* Final result: (n-t)! · (n-t)^exp1 · (n-t+1)^exp2 . */
    seq_t res = fact;
    res *= pow1;
    res *= pow2;

    return res;
}
